package dev.solyanka.utility
import org.junit.jupiter.api.Test
import kotlin.test.*
import com.google.gson.*
import java.nio.file.Path
import dev.solyanka.ui.HudLayout
class ReleaseOneTest {
 @Test fun `new feature defaults migrate from old empty objects`() {assertEquals(FeatureSettings(),FeatureCodec.decode(JsonObject()))}
 @Test fun `all blur modes roundtrip and remain bounded`() {for(mode in BlurPolicy.modes) {val f=FeatureSettings(motionBlur=MotionBlurSettings(mode=mode));assertEquals(f,FeatureCodec.decode(Gson().toJsonTree(f).asJsonObject));assertTrue(BlurPolicy.factor(f.motionBlur) in 0f..1f)}}
 @Test fun `blur rejects unported modes and invalid strengths`() {for(s in listOf(MotionBlurSettings(mode="velocity"),MotionBlurSettings(mode="hybrid"),MotionBlurSettings(strength=-.1),MotionBlurSettings(strength=2.1),MotionBlurSettings(strength=Double.NaN))) assertFails {s.validate()}}
 @Test fun `zero blur is current frame identity`() {for(m in BlurPolicy.modes) {val s=MotionBlurSettings(mode=m,strength=0.0);assertEquals(0f,BlurPolicy.factor(s));assertEquals(.3,BlurPolicy.channel(.3,.9,s),.000001)}}
 @Test fun `accumulation factors match source multipliers`() {assertEquals((1-Math.pow(.5,5.0/3)).toFloat(),BlurPolicy.factor(MotionBlurSettings(mode="accum_mix")),.000001f);assertEquals((1-Math.pow(.5,7.0/3)).toFloat(),BlurPolicy.factor(MotionBlurSettings(mode="accum_max")),.000001f)}
 @Test fun `mix holds stationary values and stays between inputs`() {for(s in listOf(0.0,.1,1.0,2.0)) {val setting=MotionBlurSettings(strength=s);assertEquals(.6,BlurPolicy.channel(.6,.6,setting),.000001);assertTrue(BlurPolicy.channel(.2,.9,setting) in .2.. .9)}}
 @Test fun `max never dims a current highlight`() {val s=MotionBlurSettings(mode="accum_max");assertEquals(.9,BlurPolicy.channel(.9,.1,s),.000001);assertTrue(BlurPolicy.channel(.1,.9,s)>.1)}
 @Test fun `history memory budget permits 4k but not unbounded sizes`() {assertTrue(BlurPolicy.sizeAllowed(3840,2160));assertTrue(BlurPolicy.sizeAllowed(1,1));for(pair in listOf(0 to 10,-1 to 10,7680 to 4320,Int.MAX_VALUE to Int.MAX_VALUE)) assertFalse(BlurPolicy.sizeAllowed(pair.first,pair.second))}
 @Test fun `new sections reject wrong types without erasing defaults`() {for(raw in listOf("""{"motionBlur":{"strength":"1"}}""","""{"dvd":{"width":92.5}}""","""{"stopwatch":{"key":null}}""","""{"stopwatch":{"device":5}}""","""{"dvd":{"sound":0}}""")) assertFails {FeatureCodec.decode(JsonParser.parseString(raw).asJsonObject)}}
 @Test fun `stopwatch idle first press starts without reporting`() {var now=20L;val c=StopwatchClock {now};assertEquals(0L,c.elapsedNanos());assertNull(c.press());assertEquals(StopwatchClock.State.RUNNING,c.state);now=42;assertEquals(22L,c.elapsedNanos())}
 @Test fun `stop press reports once and freezes elapsed`() {var now=0L;val c=StopwatchClock {now};c.press();now=123;assertEquals(123L,c.press());now=456;assertEquals(123L,c.elapsedNanos());assertEquals(StopwatchClock.State.STOPPED,c.state)}
 @Test fun `third press resets and fourth starts again`() {var now=0L;val c=StopwatchClock {now};c.press();now=1;c.press();assertNull(c.press());assertEquals(StopwatchClock.State.IDLE,c.state);assertEquals(0L,c.elapsedNanos());c.press();now=10;assertEquals(9L,c.elapsedNanos())}
 @Test fun `zero duration stop is not confused with no report`() {val c=StopwatchClock {0};c.press();assertEquals(0L,c.press())}
 @Test fun `reset running timer removes all timing state`() {var now=0L;val c=StopwatchClock {now};c.press();now=500;c.reset();assertEquals(0L,c.elapsedNanos());assertEquals(StopwatchClock.State.IDLE,c.state)}
 @Test fun `timer protects against backwards supplied clock`() {var now=10L;val c=StopwatchClock {now};c.press();now=9;assertEquals(0L,c.elapsedNanos());assertEquals(0L,c.press())}
 @Test fun `archive duration format keeps hours above 24 and milliseconds`() {assertEquals("00:00:00.000",StopwatchClock.formatNanos(-1));assertEquals("00:00:05.123",StopwatchClock.formatNanos(5_123_999_999));assertEquals("25:01:01.007",StopwatchClock.formatNanos(90_061_007_000_000));assertTrue(StopwatchClock.formatNanos(Long.MAX_VALUE).startsWith("2562047:"))}
 @Test fun `timer binding distinguishes keyboard mouse and unbound`() {assertFalse(StopwatchSettings().matches(InputDevice.KEYBOARD,-1));assertTrue(StopwatchSettings(key=65).matches(InputDevice.KEYBOARD,65));assertFalse(StopwatchSettings(key=65).matches(InputDevice.MOUSE,0));assertTrue(StopwatchSettings(device="MOUSE",key=2).matches(InputDevice.MOUSE,2))}
 @Test fun `timer binding validation matches supported GLFW ranges`() {for(s in listOf(StopwatchSettings(device="BAD"),StopwatchSettings(key=12),StopwatchSettings(device="MOUSE",key=8),StopwatchSettings(key=349))) assertFails {s.validate()};StopwatchSettings(device="MOUSE",key=0).validate();StopwatchSettings(key=348).validate()}
 @Test fun `stopwatch editor changes do not touch other HUDs or binding`() {val f=FeatureSettings(stopwatch=StopwatchSettings(key=65));val n=HudLayout.update(f,"archive.stopwatch") {it.copy(x=100,y=80,scale=2.0)};assertEquals(f.copy(stopwatch=f.stopwatch.copy(hud=f.stopwatch.hud.copy(x=100,y=80,scale=2.0))),n);assertEquals(25,HudLayout.entries(n).size)}
 @Test fun `dvd validates text dimensions radius and speed`() {for(s in listOf(DvdSettings(text="x".repeat(65)),DvdSettings(text="a\nb"),DvdSettings(width=47),DvdSettings(height=121),DvdSettings(radius=41),DvdSettings(speed=Double.POSITIVE_INFINITY),DvdSettings(speed=19.0))) assertFails {s.validate()};DvdSettings(text="").validate()}
 @Test fun `dvd first frame establishes time without a movement jump`() {val d=DvdMotion();assertFalse(d.step(1_000_000_000,500,400,DvdSettings()));assertEquals(24.0,d.x);assertEquals(24.0,d.y)}
 @Test fun `dvd source velocity and frame clamp are retained`() {val d=DvdMotion();val s=DvdSettings();d.step(0,500,400,s);d.step(1_000_000_000,500,400,s);assertEquals(28.6,d.x,.000001);assertEquals(24+.78*92*.05,d.y,.000001)}
 @Test fun `dvd paused time does not create catch up motion`() {val d=DvdMotion();d.step(0,500,400,DvdSettings());d.pause(1_000_000_000);d.step(1_000_000_000,500,400,DvdSettings());assertEquals(24.0,d.x)}
 @Test fun `tiny window never manufactures corner counts or sound events`() {val d=DvdMotion();for(i in 0..100) assertFalse(d.step(i*50_000_000L,20,10,DvdSettings()));assertEquals(0,d.cornerHits);assertEquals(0.0,d.x);assertEquals(0.0,d.y)}
 @Test fun `dvd one axis collision changes color without corner count`() {val d=DvdMotion();val s=DvdSettings();d.step(0,119,400,s);assertFalse(d.step(50_000_000,119,400,s));assertEquals(27.0,d.x);assertEquals(1,d.colorIndex);assertEquals(0,d.cornerHits);d.step(100_000_000,119,400,s);assertTrue(d.x<27)}
 @Test fun `dvd simultaneous axis hit flashes and counts once`() {val d=DvdMotion();val s=DvdSettings();d.step(0,119,65,s);assertTrue(d.step(50_000_000,119,65,s));assertEquals(1,d.cornerHits);assertEquals(42,d.flashAlpha(50_000_000));assertEquals(21,d.flashAlpha(260_000_000));assertEquals(0,d.flashAlpha(500_000_000))}
 @Test fun `dvd reset and negative monotonic epoch cannot flash before hit`() {val d=DvdMotion();assertEquals(0,d.flashAlpha(-100_000_000));d.step(0,119,65,DvdSettings());d.step(50_000_000,119,65,DvdSettings());d.reset();assertEquals(0,d.cornerHits);assertEquals(24.0,d.x);assertEquals(0,d.flashAlpha(-1))}
 @Test fun `dvd coordinates stay bounded over resize and repeated bounces`() {val d=DvdMotion();for(i in 0..500) {val w=if(i%2==0) 150 else 600;val h=if(i%3==0) 90 else 400;d.step(i*40_000_000L,w,h,DvdSettings());assertTrue(d.x in 0.0..(w-92).toDouble());assertTrue(d.y in 0.0..(h-38).toDouble());assertTrue(d.colorIndex in 0..5)}}
 @Test fun `blur uses disjoint history targets and native target format`() {val s=source("feature/TemporalBlur.kt");for(token in listOf("false,format)","GpuFormat.RGBA16_FLOAT","copy(next,main);read=next;write=previous","pass.draw(3,1,0,0)","now-lastFrame>500_000_000L","if(!seeded","writeToBuffer","destroyBuffers()")) assertTrue(s.contains(token),token);assertTrue(s.indexOf("encoder.writeToBuffer")<s.indexOf("encoder.createRenderPass"));assertFalse(s.contains("copyDepthFrom"));assertFalse(s.contains("getMainRenderTarget"))}
 @Test fun `timer input precedes command module gate and is world only`() {val s=source("SolyankaClient.kt");assertTrue(s.indexOf("ArchiveHuds.input(device,key)")<s.indexOf("if (!isEnabled(KEYBINDS))"));val a=source("feature/ArchiveHuds.kt");for(token in listOf("c.gui.screen()!=null","!c.isWindowActive","sendSystemMessage","soundPending=false")) assertTrue(a.contains(token));assertFalse(a.contains("sendCommand"));assertFalse(a.contains("sendChat"))}
 private fun source(path:String)=Path.of("src/client/kotlin/dev/solyanka/client/$path").toFile().readText()
}
